class Book:
    def __init__(self, title, author, publisher, year):
        self.title = title
        self.author = author
        self.publisher = publisher
        self.year = year
        self.is_available = True

    def borrow(self):
        if self.is_available:
            self.is_available = False
            return f"You have borrowed {self.title} by {self.author}."
        else:
            return f"{self.title} by {self.author} is not available for borrowing."

    def return_book(self):
        if not self.is_available:
            self.is_available = True
            return f"You have returned {self.title} by {self.author}."
        else:
            return f"{self.title} by {self.author} is already available."

class Patron:
    def __init__(self, name, email):
        self.name = name
        self.email = email
        self.borrowed_books = []

    def borrow_book(self, book):
        if book.is_available:
            book.borrow()
            self.borrowed_books.append(book)
            return f"You have borrowed {book.title} by {book.author}."
        else:
            return f"{book.title} by {book.author} is not available for borrowing."

    def return_book(self, book):
        if book in self.borrowed_books:
            book.return_book()
            self.borrowed_books.remove(book)
            return f"You have returned {book.title} by {book.author}."
        else:
            return f"You have not borrowed {book.title} by {book.author}."

class Library:
    def __init__(self):
        self.books = []
        self.patrons = []

    def add_book(self, book):
        self.books.append(book)

    def add_patron(self, patron):
        self.patrons.append(patron)

    def search_book(self, title):
        for book in self.books:
            if book.title == title:
                return book
        return None

    def search_patron(self, name):
        for patron in self.patrons:
            if patron.name == name:
                return patron
        return None

